}

.page-header .cat-icon {
  font-size: 3.2rem;
  display: block;
  margin-bottom: 0.75rem;
  filter: drop-shadow(0 0 18px rgba(255, 159, 67, 0.6));
}

.page-header h1 {
  font-size: clamp(1.8rem, 5vw, 2.8rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  background: linear-gradient(135deg, #e8eaf6 30%, #6c63ff);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.page-header p {
  margin-top: 0.6rem;
  color: var(--text-secondary);
  font-size: 1.05rem;
}

/* ── FAQ container ───────────────────────────────────── */
.faq-container {
  max-width: 720px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

/* ── Individual FAQ item (.example) ─────────────────── */
.example {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.example:hover {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px var(--accent-glow);
}

/* ── Question button ─────────────────────────────────── */
.question-btn {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 1.1rem 1.4rem;
  background: transparent;
  border: none;
  cursor: pointer;
  text-align: left;
  color: var(--text-primary);
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  transition: background var(--transition);
  position: relative;
}

.question-btn:hover {
  background: var(--bg-header);
}

.question-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

.question-btn .q-label {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.6rem;
  height: 1.6rem;
  border-radius: 50%;
  background: var(--accent-glow);
  color: var(--accent);
  font-size: 0.75rem;
  font-weight: 700;
  flex-shrink: 0;
  letter-spacing: 0;
}

.question-btn .q-text {
  flex: 1;
}

.question-btn .chevron {
  width: 18px;
  height: 18px;
  stroke: var(--text-muted);
  flex-shrink: 0;
  transition: transform var(--transition), stroke var(--transition);
}

.example.open .chevron {
  transform: rotate(180deg);
  stroke: var(--accent);
}

/* ── Answer (.details) ───────────────────────────────── */
.details {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}

.example.open .details {
  max-height: 600px;
}

.details-inner {
  padding: 0 1.4rem 1.3rem 1.4rem;
  padding-left: calc(1.4rem + 1.6rem + 1rem); /* align with question text */
  color: var(--text-secondary);
  font-size: 0.96rem;
  line-height: 1.75;
  border-top: 1px solid var(--border);
  padding-top: 1rem;
}

.details-inner a {
  color: var(--cat-orange);
  text-decoration: none;
}
.details-inner a:hover {
  text-decoration: underline;
}

