  chevron.setAttribute("stroke-width", "2.5");
  chevron.setAttribute("stroke-linecap", "round");
  chevron.setAttribute("stroke-linejoin", "round");
  chevron.setAttribute("aria-hidden", "true");
  const path = document.createElementNS("http://www.w3.org/2000/svg", "polyline");
  path.setAttribute("points", "6 9 12 15 18 9");
  chevron.appendChild(path);

  btn.append(label, text, chevron);

  // Answer panel
  const details = document.createElement("div");
  details.className = "details";

  const inner = document.createElement("div");
  inner.className = "details-inner";
  inner.textContent = answer;
  details.appendChild(inner);

  // Toggle behaviour
  btn.addEventListener("click", () => {
    const isOpen = wrapper.classList.toggle("open");
    btn.setAttribute("aria-expanded", String(isOpen));
  });

  wrapper.append(btn, details);
  return wrapper;
}

/**
 * Renders the full FAQ list into #app.
 */
function App() {
  const root = document.getElementById("app");

  // Header
  const header = document.createElement("header");
  header.className = "page-header";
  header.innerHTML = `
    <span class="cat-icon" aria-hidden="true">🐱</span>
    <h1>Everything About Cats</h1>
    <p>Click a question to reveal the answer.</p>
  `;

  // FAQ list
  const container = document.createElement("main");
  container.className = "faq-container";
  container.setAttribute("role", "list");

  faqs.forEach((item, i) => {
    container.appendChild(FAQItem({ ...item, index: i }));
  });

  // Footer
  const footer = document.createElement("footer");
  footer.className = "page-footer";
  footer.textContent = "Crafted with curiosity — and a little catnip.";

  root.append(header, container, footer);
}

// ── Bootstrap ─────────────────────────────────────────────────────────────────
document.addEventListener("DOMContentLoaded", App);
